using System.Text.Json;
using Ff7.Accessibility.LegacyLayout;

namespace Ff7.Accessibility.Reloaded;

/// <summary>Reviewed Echo-S future-route metadata. It cannot authorize a current clickable target.</summary>
public static class WholeGameEchoFutureMetadata
{
    private static readonly IReadOnlyDictionary<int, Layout> Rows = RawRows.Split('\n', StringSplitOptions.RemoveEmptyEntries)
        .Select(line => JsonSerializer.Deserialize<Layout>(line) ?? throw new InvalidOperationException("Invalid Echo-S future metadata"))
        .ToDictionary(row => row.Field);

    internal static FieldScriptNavigationReadResult? Read(int field) => Rows.TryGetValue(field, out var row)
        ? new(true, row.Transitions, row.Exits, [], [], "Reviewed future Echo-S metadata; current loaded identity required before traversal") : null;
    internal static IReadOnlyList<Gateway> Gateways(int field) => Rows[field].Gateways;
    internal static IReadOnlyList<FieldEntryPlacementResult> Arrivals(int field, string exit, int destination) =>
        Rows[field].Arrivals.Where(a => a.Exit == exit && a.Destination == destination).Select(a => a.Placement).Distinct().ToArray();

    internal static FieldStoryEventDefinition RemapGatewayStory(FieldStoryEventDefinition definition)
    {
        if (definition.SourceScriptType?.StartsWith("Gateway", StringComparison.OrdinalIgnoreCase) != true ||
            !Rows.TryGetValue(definition.FieldId, out var row)) return definition;
        var matches = row.StockGateways.Where(g => (g.Start[0] + g.End[0]) / 2 == definition.X &&
            (g.Start[1] + g.End[1]) / 2 == definition.Y && (g.Start[2] + g.End[2]) / 2 == definition.Z).ToArray();
        if (matches.Length != 1) return definition;
        var current = row.Gateways.SingleOrDefault(g => g.Index == matches[0].Index);
        if (current is null) return definition;
        return definition with { X = (current.Start[0] + current.End[0]) / 2, Y = (current.Start[1] + current.End[1]) / 2,
            Z = (current.Start[2] + current.End[2]) / 2, TriggerLine = current.Line };
    }

    internal sealed record Gateway(int Index, int Destination, int[] Start, int[] End, int ArrivalX, int ArrivalY, int ArrivalTriangle)
    { public FieldNavigationTriggerLine Line => new(Start[0], Start[1], Start[2], End[0], End[1], End[2]); }
    private sealed record Arrival(string Exit, int Destination, FieldEntryPlacementResult Placement);
    private sealed record Layout(int Field, FieldNavigationTarget[] Exits, FieldScriptNavigationTransition[] Transitions, Gateway[] Gateways, Arrival[] Arrivals, Gateway[] StockGateways);

    // Full native transfer/control-flow derivation SHA256 a7d1c008abefb7c5fae0e19fd53a0210e873cab76a16a44a1e02b0c806d3ca06. Unknown or
    // ambiguous entry placement is excluded; no stock-script arrival guess is used.
